import ast
from pathlib import Path

violations = []
for path in Path('reportgen').glob('*.py'):
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in ast.walk(tree):
        if isinstance(node, ast.Subscript) and isinstance(node.value, ast.Name):
            if node.value.id in {'cfg', 'config'}:
                violations.append(f'{path}:{node.lineno}: {node.value.id} is subscripted')
if violations:
    raise SystemExit('\n'.join(violations))
print('No cfg/config subscripting found in reportgen/')
